const sunData = $('Sunset/sunrise in Bcn').first().json.results;
const sunriseDate = new Date(sunData.sunrise);
const sunsetDate = new Date(sunData.sunset);

// Reuse today's sunrise/sunset *time of day* across the 5-day window —
// shifts by only ~1-2 min/day in June, negligible for display purposes.
const sunriseHourUTC = sunriseDate.getUTCHours() + sunriseDate.getUTCMinutes() / 60;
const sunsetHourUTC = sunsetDate.getUTCHours() + sunsetDate.getUTCMinutes() / 60;

return items.map(item => {
  const data = item.json;
  if (!data.passes) return item;

  const passes = data.passes.map(p => {
    const d = new Date(p.startUTC * 1000);
    const passHourUTC = d.getUTCHours() + d.getUTCMinutes() / 60;
    const isDaylight = passHourUTC >= sunriseHourUTC && passHourUTC <= sunsetHourUTC;
    return { ...p, isDaylight };
  });

  return { json: { ...data, passes } };
});
